bus=dbus.SystemBus(private=True);objects=dbus.Interface(bus.get_object('org.freedesktop.ModemManager1','/org/freedesktop/ModemManager1'),'org.freedesktop.DBus.ObjectManager').GetManagedObjects();v=next(x for x in objects.values() if 'org.freedesktop.ModemManager1.Modem' in x);loc=v['org.freedesktop.ModemManager1.Modem.Location'];watch=json.loads((r/'gnss-assist/watch-state.json').read_text());assert int(loc['Enabled'])==0 and not loc['SignalsLocation'] and not watch['active'] and watch['running'] and watch['time_prepared'] and watch['time_preparation_completions']>0 and int(v['org.freedesktop.ModemManager1.Modem']['PowerState'])==1;bus.close();q=base/'baseline90-request';assert not q.exists();q.write_bytes(b'baseline90\n');print(json.dumps(dict(stage=246,baseline_request_written=True,first_startup_diag_live=True,time_prepared=True,mm_power=1)))
